${pagingTop} SELECT ROW_NUMBER() OVER (ORDER BY lecture_id) AS reverse_rownum, homepage_id, course_id,lecture_id,lecture_title,edu_start_date,edu_end_date,edu_start_time,edu_end_time,request_start_date, request_end_date,edu_school,online_person_count,offline_person_count,wait_person_count,request_type,teacher_name, teacher_tel,supporter_name,supporter_tel,edu_school_map,lecture_content,add_date,add_ip,add_id,edu_address_1, edu_address_2,teacher_id,day_week,edu_second_school FROM LECTURE_INFO WHERE homepage_id = #{homepage_id}
AND ${search_type} LIKE '%'||#{search_text}||'%'
AND course_id = #{searching_course_id}
AND request_start_date > TO_CHAR(SYSDATE, 'yyyy-MM-dd')
AND request_start_date <= TO_CHAR(SYSDATE, 'yyyy-MM-dd') AND request_end_date >= TO_CHAR(SYSDATE, 'yyyy-MM-dd')
AND request_end_date < TO_CHAR(SYSDATE, 'yyyy-MM-dd')
AND edu_start_date > TO_CHAR(SYSDATE, 'yyyy-MM-dd')
AND edu_start_date <= TO_CHAR(SYSDATE, 'yyyy-MM-dd') AND edu_end_date >= TO_CHAR(SYSDATE, 'yyyy-MM-dd')
AND edu_end_date < TO_CHAR(SYSDATE, 'yyyy-MM-dd')
AND request_type = #{searching_request_type}
AND request_end_date >= #{start_period}
AND request_start_date <= #{end_period}
ORDER BY lecture_id DESC ${pagingBottom}

